/**
 * Bloc de code MDX : coloration via Prism (react-syntax-highlighter).
 * Thème VS Code (vs / vscDarkPlus) selon le mode clair/sombre du site.
 */
export function CodeBlock({ children, language = 'typescript', className }: CodeBlockProps) {
  const { resolvedTheme } = useTheme();
  const syntaxStyle = getPrismSyntaxStyle(resolvedTheme === 'dark' ? 'dark' : 'light');

  const code =
    typeof children === 'string'
      ? children.trim()
      : Array.isArray(children)
        ? children.map(String).join('').trim()
        : String(children ?? '').trim();

  return (
    <div className={cn('not-prose relative my-6', className)}>
      <SyntaxHighlighter
        language={language}
        style={syntaxStyle}
        customStyle={codeBlockCustomStyle}
        codeTagProps={{
          style: {
            fontFamily: codeBlockCustomStyle.fontFamily,
            fontSize: codeBlockCustomStyle.fontSize,
          },
        }}
      >
        {code}
      </SyntaxHighlighter>
    </div>
  );
}

