import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import type { PlotProps } from '../types';

/**
 * DistributionPlot
 *
 * Composant de visualisation pour afficher le graphique d'une distribution.
 * Utilise Recharts pour le rendu et met en cache les calculs pour optimiser les performances.
 */
export function DistributionPlot({ distribution, calculator, cache }: PlotProps) {
  // Calcul des points pour le graphique avec mise en cache
  const plotData = React.useMemo(() => {
    if (!distribution.range || !calculator?.pdf || !cache) {
      console.warn('Missing required props:', {
        hasRange: !!distribution.range,
        hasCalculator: !!calculator?.pdf,
        hasCache: !!cache,
      });
      return [];
    }

    const points = [];
    const { min, max } = distribution.range;
    const step = (max - min) / 100;

    for (let x = min; x <= max; x += step) {
      // Utilisation du cache pour éviter les recalculs
      const cacheKey = `pdf_${x.toFixed(4)}`;
      let y = cache.get(cacheKey);

      if (y === undefined) {
        try {
          y = calculator.pdf(x);
          if (typeof y === 'number' && !isNaN(y)) {
            cache.set(cacheKey, y);
          } else {
            console.warn('Invalid y value:', y);
            continue;
          }
        } catch (error) {
          console.error('Error calculating pdf:', error);
          continue;
        }
      }

      points.push({ x, y });
    }

    return points;
  }, [distribution, calculator, cache]);

  if (!plotData.length) {
    return null;
  }

  return (
    <div className="h-[400px] w-full">
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={plotData}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis
            dataKey="x"
            type="number"
            domain={['auto', 'auto']}
            tickFormatter={(value) => value.toFixed(2)}
          />
          <YAxis domain={[0, 'auto']} tickFormatter={(value) => value.toFixed(3)} />
          <Tooltip
            formatter={(value: number) => value.toFixed(4)}
            labelFormatter={(label: number) => `x = ${label.toFixed(2)}`}
          />
          <Line type="monotone" dataKey="y" stroke="#8884d8" dot={false} name="Density" />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

import React from 'react';
import { DistributionPlot } from './DistributionPlot';
import { CurveCalculator } from './CurveCalculator';
import { PresetManager } from './PresetManager';
import { useCalculationCache } from '@/hooks/useCalculationCache';
import { DistributionConfig } from '@/types/distributions';
import type { CurveData } from './CurveCalculator/types';

interface DistributionVisualizerProps {
  distribution: DistributionConfig;
}

export function DistributionVisualizer({ distribution }: DistributionVisualizerProps) {
  const cache = useCalculationCache<number>();
  const [, setCurveData] = React.useState<CurveData | null>(null);

  const defaultParams = React.useMemo(() => {
    return distribution.parameters.reduce(
      (acc, param) => {
        acc[param.name] = param.defaultValue;
        return acc;
      },
      {} as Record<string, number>
    );
  }, [distribution]);

  const calculator = React.useMemo(
    () => ({
      pdf: (x: number) => {
        const pdf = distribution.functions.pdf;
        if (!pdf) {
          throw new Error(`PDF is not defined for ${distribution.name}`);
        }
        return pdf(defaultParams, x);
      },
    }),
    [distribution, defaultParams]
  );

  const defaultCurve = React.useMemo(
    () => ({
      id: 'default',
      color: '#8884d8',
      parameters: defaultParams,
    }),
    [defaultParams]
  );

  const handleDataCalculated = React.useCallback((data: CurveData) => {
    setCurveData(data);
  }, []);

  return (
    <div className="space-y-4">
      <DistributionPlot distribution={distribution} calculator={calculator} cache={cache} />
      <CurveCalculator
        distribution={distribution}
        curve={defaultCurve}
        functionType="pdf"
        onDataCalculated={handleDataCalculated}
      />
      <PresetManager />
    </div>
  );
}

