import { useRef, useCallback } from 'react';

interface CacheEntry<T> {
  key: string;
  value: T;
  timestamp: number;
}

interface CacheOptions {
  maxSize?: number;
  ttl?: number; // Time to live en millisecondes
}

export function useCalculationCache<T>(options: CacheOptions = {}) {
  const { maxSize = 100, ttl = 5000 } = options;
  const cacheRef = useRef<Map<string, CacheEntry<T>>>(new Map());

  const generateKey = useCallback((params: unknown) => {
    return JSON.stringify(params, (_, value) => {
      if (value && typeof value === 'object' && !Array.isArray(value)) {
        return Object.keys(value as Record<string, unknown>)
          .sort()
          .reduce<Record<string, unknown>>((acc, key) => {
            acc[key] = (value as Record<string, unknown>)[key];
            return acc;
          }, {});
      }
      return value;
    });
  }, []);

  const get = useCallback(
    (key: string): T | undefined => {
      const entry = cacheRef.current.get(key);
      if (!entry) return undefined;

      const now = Date.now();
      if (now - entry.timestamp > ttl) {
        cacheRef.current.delete(key);
        return undefined;
      }

      return entry.value;
    },
    [ttl]
  );

  const set = useCallback(
    (key: string, value: T) => {
      if (cacheRef.current.size >= maxSize) {
        // Supprimer l'entrée la plus ancienne
        const oldestKey = Array.from(cacheRef.current.entries()).sort(
          ([, a], [, b]) => a.timestamp - b.timestamp
        )[0][0];
        cacheRef.current.delete(oldestKey);
      }

      cacheRef.current.set(key, {
        key,
        value,
        timestamp: Date.now(),
      });
    },
    [maxSize]
  );

  const clear = useCallback(() => {
    cacheRef.current.clear();
  }, []);

  return {
    generateKey,
    get,
    set,
    clear,
  };
}

import { useMemo } from 'react';
import { useCalculationCache } from './useCalculationCache';
import { DistributionConfig } from '@/types/distributions';

export interface Curve {
  id: string;
  distributionName: string;
  params: Record<string, number>;
  color?: string;
}

interface CalculationOptions {
  xMin: number;
  xMax: number;
  points: number;
}

interface CalculationResult {
  xValues: number[];
  yValues: number[];
}

const DEFAULT_OPTIONS: CalculationOptions = {
  xMin: -5,
  xMax: 5,
  points: 200,
};

function generateXValues(options: CalculationOptions): number[] {
  const { xMin, xMax, points } = options;
  const step = (xMax - xMin) / (points - 1);
  return Array.from({ length: points }, (_, i) => xMin + i * step);
}

function calculateYValues(
  fn: (params: Record<string, number>, x: number) => number,
  params: Record<string, number>,
  xValues: number[]
): number[] {
  return xValues.map((x) => fn(params, x));
}

export function useDistributionCalculator(
  distribution: DistributionConfig,
  params: Record<string, number>,
  functionType: 'pdf' | 'cdf',
  options: Partial<CalculationOptions> = {}
): CalculationResult {
  const cache = useCalculationCache<CalculationResult>();
  const mergedOptions = { ...DEFAULT_OPTIONS, ...options } as CalculationOptions;

  return useMemo(() => {
    const cacheKey = JSON.stringify({
      distribution: distribution.name,
      params,
      functionType,
      options: mergedOptions,
    });
    const cachedResult = cache.get(cacheKey);

    if (cachedResult) return cachedResult;

    const xValues = generateXValues(mergedOptions);

    const fn = distribution.functions[functionType];
    if (!fn) {
      throw new Error(
        `La fonction ${functionType} n'est pas définie pour la distribution ${distribution.name}`
      );
    }

    const yValues = calculateYValues(fn, params, xValues);
    const result: CalculationResult = { xValues, yValues };

    cache.set(cacheKey, result);
    return result;
  }, [distribution, params, functionType, mergedOptions, cache]);
}

import { useState, useEffect } from 'react';

export function useTreeNodeState(href: string | undefined, isPathActive: boolean) {
  const [isExpanded, setIsExpanded] = useState(isPathActive);
  const [isClient, setIsClient] = useState(false);

  useEffect(() => {
    setIsClient(true);
    if (href) {
      const stored = localStorage.getItem(`toctree-${href}`);
      if (stored === 'expanded' || isPathActive) {
        setIsExpanded(true);
      }
    }
  }, [href, isPathActive]);

  useEffect(() => {
    if (href && isClient) {
      const key = `toctree-${href}`;
      if (isExpanded) {
        localStorage.setItem(key, 'expanded');
      } else {
        localStorage.removeItem(key);
      }
    }
  }, [isExpanded, href, isClient]);

  return [isExpanded, setIsExpanded] as const;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { routing } from '@/i18n/routing';
import type { BlogPost, BlogPostDetail, BlogPostKind } from '@/types/blog';

const CONTENT_ROOT = path.join(process.cwd(), 'src/content');

const VALID_KINDS = new Set<BlogPostKind>(['thought', 'research']);

export function getBlogDirectory(locale: string): string {
  return path.join(CONTENT_ROOT, locale, 'blog');
}

function resolveBlogDirectory(locale: string): string {
  const preferred = getBlogDirectory(locale);
  if (fs.existsSync(preferred)) {
    return preferred;
  }
  return getBlogDirectory(routing.defaultLocale);
}

export function resolveBlogFilePath(locale: string, slug: string): string | null {
  const localesToTry =
    locale === routing.defaultLocale ? [locale] : [locale, routing.defaultLocale];

  for (const loc of localesToTry) {
    const filePath = path.join(getBlogDirectory(loc), `${slug}.mdx`);
    if (fs.existsSync(filePath)) {
      return filePath;
    }
  }

  return null;
}

export function listBlogFileNames(locale: string): string[] {
  const directory = resolveBlogDirectory(locale);

  if (!fs.existsSync(directory)) {
    return [];
  }

  return fs.readdirSync(directory).filter((fileName) => fileName.endsWith('.mdx'));
}

function isValidBlogFrontmatter(data: Record<string, unknown>): boolean {
  return (
    typeof data.title === 'string' &&
    typeof data.description === 'string' &&
    typeof data.date === 'string' &&
    typeof data.kind === 'string' &&
    VALID_KINDS.has(data.kind as BlogPostKind)
  );
}

export function getBlogPosts(locale: string): BlogPost[] {
  const directory = resolveBlogDirectory(locale);
  const fileNames = fs.existsSync(directory)
    ? fs.readdirSync(directory).filter((fileName) => fileName.endsWith('.mdx'))
    : [];

  const posts: BlogPost[] = [];

  for (const fileName of fileNames) {
    try {
      const slug = fileName.replace(/\.mdx$/, '');
      const fullPath = path.join(directory, fileName);
      const fileContents = fs.readFileSync(fullPath, 'utf8');
      const { data } = matter(fileContents);

      if (!isValidBlogFrontmatter(data)) {
        console.warn(`Article blog invalide ${fileName}: frontmatter incomplet`);
        continue;
      }

      if (data.visible === false) {
        continue;
      }

      posts.push({
        slug,
        title: data.title,
        description: data.description,
        date: data.date,
        kind: data.kind as BlogPostKind,
        tags: Array.isArray(data.tags) ? data.tags.map(String) : [],
        visible: data.visible !== false,
      });
    } catch (error) {
      console.warn(`Impossible de lire ${fileName}:`, error);
    }
  }

  return posts.sort((a, b) => b.date.localeCompare(a.date));
}

export function getBlogPost(locale: string, slug: string): BlogPostDetail | null {
  const filePath = resolveBlogFilePath(locale, slug);
  if (!filePath) {
    return null;
  }

  try {
    const fileContents = fs.readFileSync(filePath, 'utf8');
    const { data, content } = matter(fileContents);

    if (!isValidBlogFrontmatter(data) || data.visible === false) {
      return null;
    }

    return {
      post: {
        slug,
        title: data.title,
        description: data.description,
        date: data.date,
        kind: data.kind as BlogPostKind,
        tags: Array.isArray(data.tags) ? data.tags.map(String) : [],
        visible: data.visible !== false,
      },
      source: content,
    };
  } catch {
    return null;
  }
}

