export type OptionType = 'call' | 'put';

export interface BlackScholesParams {
  spot: number;
  strike: number;
  timeYears: number;
  rate: number;
  volatility: number;
  optionType: OptionType;
}

function normPdf(x: number): number {
  return Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);
}

/** Cumulative standard normal distribution (Abramowitz & Stegun). */
export function normCdf(x: number): number {
  const t = 1 / (1 + 0.2316419 * Math.abs(x));
  const d = 0.3989423 * Math.exp((-x * x) / 2);
  const p =
    d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));
  return x > 0 ? 1 - p : p;
}

function d1d2(spot: number, strike: number, timeYears: number, rate: number, volatility: number) {
  const sqrtT = Math.sqrt(timeYears);
  const d1 =
    (Math.log(spot / strike) + (rate + 0.5 * volatility * volatility) * timeYears) /
    (volatility * sqrtT);
  const d2 = d1 - volatility * sqrtT;
  return { d1, d2, sqrtT };
}

/** European Black–Scholes option price. */
export function blackScholesPrice(params: BlackScholesParams): number {
  const { spot, strike, timeYears, rate, volatility, optionType } = params;
  if (timeYears <= 0) {
    return intrinsicValue(spot, strike, optionType);
  }
  if (spot <= 0 || strike <= 0 || volatility <= 0) {
    return intrinsicValue(spot, strike, optionType);
  }

  const { d1, d2 } = d1d2(spot, strike, timeYears, rate, volatility);
  const discount = Math.exp(-rate * timeYears);

  if (optionType === 'call') {
    return spot * normCdf(d1) - strike * discount * normCdf(d2);
  }
  return strike * discount * normCdf(-d2) - spot * normCdf(-d1);
}

export function intrinsicValue(spot: number, strike: number, optionType: OptionType): number {
  if (optionType === 'call') {
    return Math.max(spot - strike, 0);
  }
  return Math.max(strike - spot, 0);
}

export interface OptionGreeks {
  delta: number;
  gamma: number;
  /** Theta per calendar day (option value change for +1 day). */
  thetaPerDay: number;
  /** Vega per 1 point of volatility (σ = 0.20 → 1 point = +0.01 absolute). */
  vegaPerVolPoint: number;
}

/** Greeks for a long option position (European BS). */
export function blackScholesGreeks(params: BlackScholesParams): OptionGreeks {
  const { spot, strike, timeYears, rate, volatility, optionType } = params;

  if (timeYears <= 1e-6 || spot <= 0 || strike <= 0 || volatility <= 0) {
    const callItm = spot > strike ? 1 : spot < strike ? 0 : 0.5;
    const putItm = spot < strike ? -1 : spot > strike ? 0 : -0.5;
    return {
      delta: optionType === 'call' ? callItm : putItm,
      gamma: 0,
      thetaPerDay: 0,
      vegaPerVolPoint: 0,
    };
  }

  const { d1, d2, sqrtT } = d1d2(spot, strike, timeYears, rate, volatility);
  const pdf = normPdf(d1);
  const discount = Math.exp(-rate * timeYears);

  const delta = optionType === 'call' ? normCdf(d1) : normCdf(d1) - 1;

  const gamma = pdf / (spot * volatility * sqrtT);

  const thetaPerYear =
    optionType === 'call'
      ? (-(spot * pdf * volatility) / (2 * sqrtT) - rate * strike * discount * normCdf(d2)) / 365
      : (-(spot * pdf * volatility) / (2 * sqrtT) + rate * strike * discount * normCdf(-d2)) / 365;

  const vegaPerVolPoint = (spot * pdf * sqrtT) / 100;

  return {
    delta,
    gamma,
    thetaPerDay: thetaPerYear,
    vegaPerVolPoint,
  };
}

export function positionSign(isLong: boolean): number {
  return isLong ? 1 : -1;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import type { MDXRemoteSerializeResult } from 'next-mdx-remote';
import { routing } from '@/i18n/routing';
import { isValidProjectFrontmatter } from '@/lib/projects/validation';
import type { Project, ProjectDetail } from '@/types/project';

const CONTENT_ROOT = path.join(process.cwd(), 'src/content');

export function getProjectsDirectory(locale: string): string {
  return path.join(CONTENT_ROOT, locale, 'projects');
}

/** Résout le fichier MDX d'un projet (repli sur la locale par défaut si absent). */
export function resolveProjectFilePath(locale: string, slug: string): string | null {
  const localesToTry =
    locale === routing.defaultLocale ? [locale] : [locale, routing.defaultLocale];

  for (const loc of localesToTry) {
    const filePath = path.join(getProjectsDirectory(loc), `${slug}.mdx`);
    if (fs.existsSync(filePath)) {
      return filePath;
    }
  }

  return null;
}

export function listProjectFileNames(locale: string): string[] {
  const directory = getProjectsDirectory(locale);

  if (!fs.existsSync(directory)) {
    if (locale !== routing.defaultLocale) {
      return listProjectFileNames(routing.defaultLocale);
    }
    return [];
  }

  return fs.readdirSync(directory).filter((fileName) => fileName.endsWith('.mdx'));
}

function resolveProjectsDirectory(locale: string): string {
  const preferred = getProjectsDirectory(locale);
  if (fs.existsSync(preferred)) {
    return preferred;
  }
  return getProjectsDirectory(routing.defaultLocale);
}

export function getProjects(locale: string): Project[] {
  const directory = resolveProjectsDirectory(locale);
  const fileNames = fs.existsSync(directory)
    ? fs.readdirSync(directory).filter((fileName) => fileName.endsWith('.mdx'))
    : [];

  const projects: Project[] = [];

  for (const fileName of fileNames) {
    try {
      const slug = fileName.replace(/\.mdx$/, '');
      const fullPath = path.join(directory, fileName);
      const fileContents = fs.readFileSync(fullPath, 'utf8');
      const { data } = matter(fileContents);

      if (!isValidProjectFrontmatter(data)) {
        console.warn(`Projet invalide ${fileName}: données manquantes ou incorrectes`);
        continue;
      }

      if (data.visible === false) {
        continue;
      }

      projects.push({
        slug,
        id: data.id,
        title: data.title,
        description: data.description,
        image: data.image,
        date: data.date,
        category: data.category,
        tags: data.tags,
        visible: data.visible ?? true,
        link: `/projects/${slug}`,
      });
    } catch (error) {
      console.error(`Erreur lors de la lecture du projet ${fileName}:`, error);
    }
  }

  return projects.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

export interface ProjectPageData {
  project: ProjectDetail;
  source: string;
}

export function getProject(locale: string, slug: string): ProjectPageData | null {
  const fullPath = resolveProjectFilePath(locale, slug);

  if (!fullPath) {
    return null;
  }

  try {
    const fileContents = fs.readFileSync(fullPath, 'utf8');
    const { data, content } = matter(fileContents);

    if (!isValidProjectFrontmatter(data)) {
      return null;
    }

    if (data.visible === false) {
      return null;
    }

    const project: ProjectDetail = {
      id: data.id,
      title: data.title,
      description: data.description,
      image: data.image,
      date: data.date,
      category: data.category,
      tags: data.tags,
      visible: data.visible ?? true,
      slug,
      content: {
        summary: '',
        objectives: [],
        approach: '',
        technologies: [],
        results: '',
        images: [],
        conclusion: '',
      },
    };

    return {
      project,
      source: content,
    };
  } catch (error) {
    console.error(`Erreur lors du chargement du projet ${slug}:`, error);
    return null;
  }
}

